use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    // Shared resources: a and b (R2: shared by both workers, exclusive access)
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));

    let a1 = Arc::clone(&a);
    let b1 = Arc::clone(&b);
    let t1_handle = thread::spawn(move || {
        worker("t1", a1, b1);
    });

    let a2 = Arc::clone(&a);
    let b2 = Arc::clone(&b);
    let t2_handle = thread::spawn(move || {
        worker("t2", a2, b2);
    });

    // R6: main starts both workers and finishes only after both finish.
    t1_handle.join().expect("t1 panicked");
    t2_handle.join().expect("t2 panicked");

    // R9: exactly this line, then exit.
    println!("DONE t1=1 t2=1");
}

fn worker(name: &str, a: Arc<Mutex<()>>, b: Arc<Mutex<()>>) {
    // R3: hold both locks at the same time during critical work.
    // R5: both workers acquire in the same order (a, then b), so a cycle
    //     (each holding one lock and waiting for the other) can never form.
    let _ga = a.lock().expect("lock a poisoned"); // R4: blocks until free
    let _gb = b.lock().expect("lock b poisoned"); // R4: blocks until free

    // Critical work while holding both locks.
    println!("{}: critical work", name);

    // R7: guards drop here, releasing both locks before the worker finishes.
    drop(_gb);
    drop(_ga);
}
```

Notes on how the requirements are satisfied:

- **R1**: one main thread plus two spawned worker threads (`t1`, `t2`).
- **R2**: both workers share the same `Mutex`es `a` and `b`; a mutex can be held by only one thread at a time.
- **R3**: each worker holds both guards `_ga` and `_gb` simultaneously while doing its critical work.
- **R4**: `lock()` blocks until the lock becomes free, then continues.
- **R5**: both workers acquire the locks in the same fixed order (`a` then `b`), which makes a circular wait — and therefore deadlock — impossible.
- **R6**: the main thread spawns both workers and `join()`s them before finishing.
- **R7**: the `MutexGuard`s are dropped (explicitly, and again at scope end) before the worker function returns.
- **R8**: with no deadlock possible and blocking locks that always eventually free, every interleaving terminates.
- **R9**: the program prints exactly `DONE t1=1 t2=1` (worker lines go to stdout too, but the required `DONE t1=1 t2=1` line is printed exactly once, then the process exits).
